mapper.select:
SELECT dj.id, dj.driver_id, dj.task_transport_id, dj.status, dj.create_time, dj.update_time, dj.finish_time, au.name as driver_name, au.phone as driver_phone, tt.start_agency_id, tt.end_agency_id FROM pd_driver_job dj LEFT JOIN pd_auth_user au ON dj.driver_id = au.id LEFT JOIN pd_task_transport tt ON dj.task_transport_id = tt.id WHERE 1=1
AND dj.driver_id = #{driverId}
AND dj.status = #{status}
ORDER BY dj.create_time DESC
